import {Trace} from './trace.mjs';
const program=(body,defs='',headers='#include <stdio.h>')=>`${headers}\n${defs}\nint main(void)\n{\n${body.map(s=>'    '+s).join('\n')}\n    return (0);\n}`;
const put=(b,at,text,what,reads=[])=>b.step(at,'Write output',what,'Output is appended. Read operations leave the stored values unchanged.','data → terminal',()=>b.state.output+=text,reads);

function outputLoop(id,title,start,end,reverse=false){
  const type=start.length?'char':'int',first=start,last=end,op=reverse?'--':'++',cond=reverse?'>=':'<=';
  const b=new Trace(id,title,'A loop repeats a read, output operation, and update until its condition is false.',program([`char c = '${first}';`,`while (c ${cond} '${last}')`,'{','    putchar(c);',`    c${op};`,'}',"putchar('\\n');"]));
  b.step(`char c = '${first}';`,'Initialize the character',`Store '${first}' in c.`,'A char stores a character code. Incrementing it moves to the next code in this illustrative basic character set.',`${first} → c`,()=>b.cell('c','c',type,0x1000,first));
  for(let code=first.charCodeAt(0);reverse?code>=last.charCodeAt(0):code<=last.charCodeAt(0);code+=reverse?-1:1){const c=String.fromCharCode(code);b.step(`while (c ${cond} '${last}')`,'Test the condition',`'${c}' ${cond} '${last}' is true. Run the loop body.`,'The condition only reads c.','condition → true',()=>{},['c']);put(b,'putchar(c);',c,`Read '${c}' and print it.`,['c']);b.step(`c${op};`,'Update the character',`Change c from '${c}' to '${String.fromCharCode(code+(reverse?-1:1))}'.`,'This update allows the loop to make progress.','c → next code',()=>b.set('c',String.fromCharCode(code+(reverse?-1:1))),['c']);}
  b.step(`while (c ${cond} '${last}')`,'Stop the loop','The updated c is outside the chosen range, so the condition is false.','No more characters are printed.','condition → false',()=>{},['c']);return b.finish("putchar('\\n');",'\n','Print a newline in this teaching main. It is not an extra requirement for the exercise function.');
}
function sign(){const b=new Trace('sign','Conditions & signs','Choose a branch using the sign of an integer.',program(['int n = -3;','if (n < 0)',"    putchar('N');",'else',"    putchar('P');","putchar('\\n');"]));b.step('int n = -3;','Create n','Initialize n to -3.','The minus sign belongs to the integer value.','-3 → n',()=>b.cell('n','n','int',0x1000,-3));b.step('if (n < 0)','Choose the negative branch','-3 < 0 is true, so execute the N branch.','Only one branch executes. The else branch is skipped.','n < 0 → true',()=>{},['n']);put(b,"putchar('N');",'N','The selected branch prints N.');return b.finish("putchar('\\n');",'\n');}
function digit(){const b=new Trace('digit','Integer → printed digits','Division and remainder separate decimal digits from an integer.',program(['int n = 42;','int tens = n / 10;','int units = n % 10;','char c = tens + \'0\';','putchar(c);','c = units + \'0\';','putchar(c);',"putchar('\\n');"]));b.step('int n = 42;','Create the number','Store numeric value 42.','42 is an integer, not yet the two printable characters 4 and 2.','42 → n',()=>b.cell('n','n','int',0x1000,42));b.step('int tens = n / 10;','Compute the tens','Integer division 42 / 10 yields 4.','The fractional part is discarded for this positive integer division.','n / 10 → tens',()=>b.cell('tens','tens','int',0x1004,4),['n']);b.step('int units = n % 10;','Compute the units','42 % 10 yields the remaining 2.','42 = 4 × 10 + 2.','n % 10 → units',()=>b.cell('units','units','int',0x1008,2),['n']);b.step("char c = tens + '0';",'Convert a digit to a char',"Adding numeric digit 4 to '0' gives printable '4'.",'C guarantees that the decimal digit character codes are consecutive.',"4 + '0' → '4'",()=>b.cell('c','c','char',0x1010,'4'),['tens']);put(b,'putchar(c);','4','Print the character 4.',['c']);b.step("c = units + '0';",'Convert the second digit',"2 + '0' gives printable '2'.",'The character is different from the numeric integer 2.',"2 + '0' → '2'",()=>b.set('c','2'),['units']);put(b,'putchar(c);','2','Print the second digit.',['c']);return b.finish("putchar('\\n');",'\n');}
function combinations(){const b=new Trace('combinations','Nested loops & unique combinations','A small 0–3 example exposes the rule a < b < c without a long terminal listing.',program(['int a;','int b;','int c;','a = 0;','while (a <= 1)','{','    b = a + 1;','    while (b <= 2)','    {','        c = b + 1;','        while (c <= 3)','        {','            printf("%d%d%d ", a, b, c);','            c++;','        }','        b++;','    }','    a++;','}',"putchar('\\n');"]));for(const [id,loc]of [['a',0x1000],['b',0x1004],['c',0x1008]])b.step(`int ${id};`,'Create a loop variable',`Reserve local ${id}.`,'Each nested loop has its own counter.',`${id} created`,()=>b.cell(id,id,'int',loc,undefined));b.step('a = 0;','Start the outer loop','Set a to 0.','This miniature example uses digits 0 through 3. The assignment’s full range is in its requirements.','0 → a',()=>b.set('a',0));for(let a=0;a<=1;a++){b.step('while (a <= 1)','Check the outer loop',`${a} <= 1 is true.`,'a chooses the first digit.','condition → true',()=>{},['a']);b.step('b = a + 1;','Start b after a',`Set b to ${a+1}.`,'b > a prevents duplicates and reversed orders.','a + 1 → b',()=>b.set('b',a+1),['a']);for(let v=a+1;v<=2;v++){b.step('while (b <= 2)','Check the middle loop',`${v} <= 2 is true.`,'There must be room for a greater third digit.','condition → true',()=>{},['b']);b.step('c = b + 1;','Start c after b',`Set c to ${v+1}.`,'c > b ensures three distinct increasing digits.','b + 1 → c',()=>b.set('c',v+1),['b']);for(let c=v+1;c<=3;c++){b.step('while (c <= 3)','Check the inner loop',`${c} <= 3 is true.`,'This is one complete valid combination.','condition → true',()=>{},['c']);put(b,'printf("%d%d%d ", a, b, c);',`${a}${v}${c} `,`Print ${a}${v}${c}; the counters are read, not changed.`,['a','b','c']);b.step('c++;','Advance c',`Increase c to ${c+1}.`,'Only the innermost counter changes.','c + 1 → c',()=>b.set('c',c+1),['c']);}b.step('while (c <= 3)','End the inner loop','c is now 4, so 4 <= 3 is false.','Control returns to the middle loop.','false → middle loop',()=>{},['c']);b.step('b++;','Advance b',`Increase b to ${v+1}.`,'The next inner loop will reset c from this new b.','b + 1 → b',()=>b.set('b',v+1),['b']);}b.step('while (b <= 2)','End the middle loop','b is now 3, so 3 <= 2 is false.','Control returns to the outer loop.','false → outer loop',()=>{},['b']);b.step('a++;','Advance a',`Increase a to ${a+1}.`,'b and c will be reset relative to the new a.','a + 1 → a',()=>b.set('a',a+1),['a']);}b.step('while (a <= 1)','End the outer loop','a is 2, so the condition is false.','All four combinations of three digits from 0–3 were produced.','false → finish',()=>{},['a']);return b.finish("putchar('\\n');",'\n');}
function iterative(power=false){const id=power?'power-loop':'factorial-loop',decs=power?['int base = 2;','int exponent = 3;','int result = 1;','int i = 0;']:['int n = 4;','int result = 1;','int i = 1;'],condition=power?'while (i < exponent)':'while (i <= n)',mul=power?'result = result * base;':'result = result * i;';const b=new Trace(id,power?'Power · repeated multiplication':'Factorial · iterative accumulation','Keep an accumulated result and update it on each loop iteration.',program([...decs,condition,'{','    '+mul,'    i++;','}','printf("%d\\n", result);']));const vars=power?[['base',2],['exponent',3],['result',1],['i',0]]:[['n',4],['result',1],['i',1]];vars.forEach(([id,v],k)=>b.step(`int ${id} = ${v};`,'Initialize '+id,`Store ${v} in ${id}.`,id==='result'?'Starting at 1 is the identity for multiplication.':'Inputs and counters have separate storage.',`${v} → ${id}`,()=>b.cell(id,id,'int',0x1000+4*k,v)));let result=1;for(let i=power?0:1;power?i<3:i<=4;i++){b.step(condition,'Check the loop','The current counter still satisfies the loop condition.','No stored value changes during the check.','condition → true',()=>{},['i',power?'exponent':'n']);const before=result;result*=power?2:i;b.step(mul,'Multiply the accumulated result',`${before} × ${power?2:i} = ${result}. Store the product back in result.`,'The old result is read before the new result replaces it.','old result × factor → result',()=>b.set('result',result),['result',power?'base':'i']);b.step('i++;','Advance the counter',`Increment i to ${i+1}.`,'This makes the loop move toward its stopping condition.','i + 1 → i',()=>b.set('i',i+1),['i']);}b.step(condition,'Stop the loop','The counter no longer satisfies the condition.','For this small example all multiplications fit in int. Signed integer overflow would not be a valid result.','condition → false',()=>{},['i',power?'exponent':'n']);return b.finish('printf("%d\\n", result);',`${result}\n`);}
function recursive(kind){const fib=kind==='fibonacci',power=kind==='power',id=fib?'fibonacci':power?'power-recursive':'factorial-recursive',fn=fib?'fib':power?'power':'factorial',signature=power?'int power(int base, int n)':`int ${fn}(int n)`,body=fib?['    int left;','    int right;','    if (n < 2)','        return (n);','    left = fib(n - 1);','    right = fib(n - 2);','    return (left + right);']:['    int smaller;','    if (n == 0)','        return (1);',`    smaller = ${fn}(${power?'base, ':''}n - 1);`,`    return (${power?'base':'n'} * smaller);`],defs=`${signature}\n{\n${body.join('\n')}\n}`,call=power?'power(2, 3)':`${fn}(${fib?3:4})`,b=new Trace(id,fib?'Fibonacci · branches and returns':power?'Power · recursive returns':'Factorial · recursive returns','Each recursive call has its own parameters and pauses until a smaller call returns.',program([`int result = ${call};`,'printf("%d\\n", result);'],defs));let serial=0;
  function visit(n){const k=serial++,scope=fn+'('+n+') #'+k,base=0x2000+k*32;b.enter(scope);b.cell('n'+k,'n','int',base,n,scope);if(power)b.cell('base'+k,'base','int',base+4,2,scope);b.capture(b.code.findIndex(l=>l===signature)+1,'Enter '+fn+'('+n+')',`Copy ${n} into this call’s own n parameter.`,'The caller waits. Each automatic n belongs to a distinct call.',`argument ${n} → new n`,[],['n'+k]);
    if(fib){b.step('int left;','Create left','Reserve local left.','It is initialized after the first child returns.','local left',()=>b.cell('left'+k,'left','int',base+4,undefined,scope));b.step('int right;','Create right','Reserve local right.','Separate statements define the order of the two recursive calls here.','local right',()=>b.cell('right'+k,'right','int',base+8,undefined,scope));}else b.step('int smaller;','Create the saved result','Reserve local smaller.','The result is initialized after the recursive child returns.','local smaller',()=>b.cell('small'+k,'smaller','int',base+8,undefined,scope));
    const cond=fib?'if (n < 2)':'if (n == 0)',stop=fib?n<2:n===0;b.step(cond,'Check the base case',`${n} ${fib?'< 2':'== 0'} is ${stop}.`,'A base case stops further recursive calls.','condition → '+stop,()=>{},['n'+k]);let result;
    if(stop){result=fib?n:1;b.step(fib?'return (n);':'return (1);','Return the base value',`Return ${result} to the waiting caller.`,'The function result is a value, not a link to the local parameter.',`${result} → caller`,()=>{},fib?['n'+k]:[]);}
    else if(fib){b.step('left = fib(n - 1);','Call the first branch',`Compute ${n-1} and pass it by value to fib.`,'The current call pauses, keeping its n.','n - 1 → child',()=>{},['n'+k]);const left=visit(n-1);b.step('left = fib(n - 1);','Receive the first result',`The first child returns ${left}; copy it into left.`,'That child’s automatic locals have ended.','returned value → left',()=>b.set('left'+k,left));b.step('right = fib(n - 2);','Call the second branch',`Compute ${n-2} and call fib.`,'The saved left result remains available.','n - 2 → child',()=>{},['n'+k]);const right=visit(n-2);b.step('right = fib(n - 2);','Receive the second result',`Copy ${right} into right.`,'The two branch results are separate values.','returned value → right',()=>b.set('right'+k,right));result=left+right;b.step('return (left + right);','Combine and return',`${left} + ${right} = ${result}. Return that value.`,'The parent receives a copy of the sum.','left + right → caller',()=>{},['left'+k,'right'+k]);}
    else{b.step(`smaller = ${fn}(${power?'base, ':''}n - 1);`,'Call the smaller problem',`Compute ${n-1} and invoke ${fn}.`,'This call pauses. The new call gets a separate n.','n - 1 → child',()=>{},['n'+k]);const small=visit(n-1);b.step(`smaller = ${fn}(${power?'base, ':''}n - 1);`,'Receive the child result',`Copy returned value ${small} into smaller.`,'The paused parent resumes with its original parameter.','child result → smaller',()=>b.set('small'+k,small));result=(power?2:n)*small;b.step(`return (${power?'base':'n'} * smaller);`,'Multiply and return',`${power?2:n} × ${small} = ${result}. Return the result.`,'Each return unwinds one call.','product → caller',()=>{},[power?'base'+k:'n'+k,'small'+k]);}
    b.leave();return result;}
  b.step(`int result = ${call};`,'Call from main',`Evaluate ${call} to obtain the initial value for result.`,'main waits for the whole recursive computation.','main → '+fn);const result=visit(fib?3:power?3:4);b.step(`int result = ${call};`,'Store the final return value',`The outermost call returns ${result}. Initialize main’s result with it.`,'All recursive calls have returned. Only main is active.','returned value → main.result',()=>b.cell('result','result','int',0x1000,result));return b.finish('printf("%d\\n", result);',`${result}\n`);}

function stringWalk(lengthOnly=false){const b=new Trace(lengthOnly?'strlen':'putstr',lengthOnly?'Length · find the zero terminator':'Print a string · one char at a time','A C string ends at the zero character; it is not counted or printed.',program(['char text[] = "Hi";','int i = 0;',"while (text[i] != '\\0')",'{',...(lengthOnly?[]:['    putchar(text[i]);']),'    i++;','}',lengthOnly?'printf("%d\\n", i);':"putchar('\\n');"]));b.step('char text[] = "Hi";','Create the C string','Create H, i, and the terminating zero.','The array has three char cells, although its string length is 2.','characters → text',()=>b.chars('text','Hi'));b.step('int i = 0;','Start at index zero','Initialize i to 0.','Index zero is the first element.','0 → i',()=>b.cell('i','i','int',0x2000,0));for(let i=0;i<2;i++){b.step("while (text[i] != '\\0')",'Check for the terminator',`text[${i}] is '${'Hi'[i]}', not zero.`,'The current char is part of the string.','char != zero → true',()=>{},['i','text'+i]);if(!lengthOnly)put(b,'putchar(text[i]);','Hi'[i],`Read and print text[${i}].`,['text'+i]);b.step('i++;','Advance the index',`Increase i to ${i+1}.`,'The bytes stay in place; only the index changes.','i + 1 → i',()=>b.set('i',i+1),['i']);}b.step("while (text[i] != '\\0')",'Reach the zero terminator','text[2] is zero, so the condition is false.','The terminator is neither counted as a text character nor printed.','zero → stop',()=>{},['i','text2']);return b.finish(lengthOnly?'printf("%d\\n", i);':"putchar('\\n');",lengthOnly?'2\n':'\n');}
function classify(kind){const config={alpha:['aB','(text[i] >= \'a\' && text[i] <= \'z\') || (text[i] >= \'A\' && text[i] <= \'Z\')',c=>/[a-zA-Z]/.test(c)],numeric:['42',"text[i] >= '0' && text[i] <= '9'",c=>/[0-9]/.test(c)],lowercase:['ab',"text[i] >= 'a' && text[i] <= 'z'",c=>/[a-z]/.test(c)],uppercase:['AB',"text[i] >= 'A' && text[i] <= 'Z'",c=>/[A-Z]/.test(c)],printable:['A!',"(unsigned char)text[i] >= 32 && (unsigned char)text[i] <= 126",c=>c.charCodeAt(0)>=32&&c.charCodeAt(0)<=126]};const [text,test,accept]=config[kind],check=`if (!(${test}))`,b=new Trace('classify-'+kind,'Character test · '+kind,'Visit the string and reject any character outside the required range.',program([`char text[] = "${text}";`,'int valid = 1;','int i = 0;',"while (text[i] != '\\0')",'{','    '+check,'        valid = 0;','    i++;','}','printf("%d\\n", valid);']));b.step(`char text[] = "${text}";`,'Create the test string','Initialize the chars and a zero terminator.','This demonstration uses basic character codes. Consult the assignment for its exact permitted ranges.','chars → array',()=>b.chars('text',text));b.step('int valid = 1;','Start with true','Initialize valid to 1.','For an empty string no character fails, so this stays 1.','1 → valid',()=>b.cell('valid','valid','int',0x2000,1));b.step('int i = 0;','Start the scan','Set i to 0.','Each character is tested once.','0 → i',()=>b.cell('i','i','int',0x2004,0));for(let i=0;i<text.length;i++){b.step("while (text[i] != '\\0')",'Check the string boundary','The current char is not zero.','Read the character within the array.','true → body',()=>{},['text'+i,'i']);b.step(check,'Test the character',`'${text[i]}' ${accept(text[i])?'belongs':'does not belong'} to the ${kind} range.`,'The negated if condition selects only a failing character.','range test → '+!accept(text[i]),()=>{},['text'+i]);if(!accept(text[i]))b.step('valid = 0;','Record failure','Set valid to 0.','A failed character makes the whole string fail.','0 → valid',()=>b.set('valid',0));b.step('i++;','Move to the next char',`Increase i to ${i+1}.`,'The string bytes are read only.','i + 1 → i',()=>b.set('i',i+1),['i']);}b.step("while (text[i] != '\\0')",'Stop at zero','The terminator ends the scan.','No data beyond the string is examined.','false → stop',()=>{},['text'+text.length]);return b.finish('printf("%d\\n", valid);','1\n');}
function caseChange(upper=true){const text=upper?'aB':'Ab',test=upper?"if (text[i] >= 'a' && text[i] <= 'z')":"if (text[i] >= 'A' && text[i] <= 'Z')",assignment=upper?"text[i] = text[i] - 'a' + 'A';":"text[i] = text[i] - 'A' + 'a';",b=new Trace(upper?'upcase':'lowcase',upper?'Change chars · uppercase':'Change chars · lowercase','Modify only characters in the matching range in this basic Latin character-set example.',program([`char text[] = "${text}";`,'int i = 0;',"while (text[i] != '\\0')",'{','    '+test,'        '+assignment,'    i++;','}','printf("%s\\n", text);']));b.step(`char text[] = "${text}";`,'Create writable chars','Create a writable char array with a zero terminator.','Use an array for a modification example. Modifying a string literal would be invalid.','chars → writable array',()=>b.chars('text',text));b.step('int i = 0;','Start the index','Set i to 0.','The scan visits each char.','0 → i',()=>b.cell('i','i','int',0x2000,0));for(let i=0;i<2;i++){b.step("while (text[i] != '\\0')",'Check the end','The char is not zero.','The loop body executes.','true → body',()=>{},['text'+i]);const doChange=upper?/[a-z]/.test(text[i]):/[A-Z]/.test(text[i]);b.step(test,'Choose whether to change',`'${text[i]}' ${doChange?'matches':'does not match'} the range.`,'Characters outside the matching range keep their values.','range test → '+doChange,()=>{},['text'+i]);if(doChange)b.step(assignment,'Write the converted char',`Convert '${text[i]}' to '${upper?text[i].toUpperCase():text[i].toLowerCase()}'.`,'The array cell itself changes. This formula uses the usual basic Latin character set.','old char code → new char code → same cell',()=>b.set('text'+i,upper?text[i].toUpperCase():text[i].toLowerCase()),['text'+i]);b.step('i++;','Advance i',`Set i to ${i+1}.`,'Only the counter changes.','i + 1 → i',()=>b.set('i',i+1));}b.step("while (text[i] != '\\0')",'Reach the terminator','The loop ends at zero.','The zero terminator remains untouched.','false → stop',()=>{},['text2']);return b.finish('printf("%s\\n", text);',`${upper?'AB':'ab'}\n`);}
function copyString(bounded=false,truncated=false){const src=truncated?'Hey':'Hi',n=truncated?2:4,decl=bounded?`char dest[${n}];`:'char dest[3];',condition=bounded?`while (i < ${n})`:"while (src[i] != '\\0')",b=new Trace(truncated?'strncpy-truncate':bounded?'strncpy-pad':'strcpy',truncated?'Bounded copy · no room for zero':bounded?'Bounded copy · zero padding':'String copy · separate storage','Copy characters into a different array. A character copy does not create an address link.',program([`char src[] = "${src}";`,decl,'int i = 0;',condition,'{',...(bounded?["    if (src[i] != '\\0')",'    {','        dest[i] = src[i];','        i++;','    }','    else','    {',`        while (i < ${n})`,'        {',"            dest[i] = '\\0';",'            i++;','        }','    }']:['    dest[i] = src[i];','    i++;']),'}',...(!bounded?["dest[i] = '\\0';"]:[]),truncated?'printf("%c%c\\n", dest[0], dest[1]);':'printf("%s\\n", dest);']));b.step(`char src[] = "${src}";`,'Create the source','Initialize source bytes plus zero.','The source and destination occupy different locations.','chars → src',()=>b.chars('s',src,0x1000,'src'));b.step(decl,'Reserve destination','Create destination cells without initial values.','Do not read a destination cell until the copy initializes it.','uninitialized → dest cells',()=>{for(let i=0;i<(bounded?n:3);i++)b.cell('d'+i,`dest[${i}]`,'char',0x1100+i,undefined,'main',{group:'array',index:i});});b.step('int i = 0;','Start at zero','Initialize i.','One index relates source and destination positions.','0 → i',()=>b.cell('i','i','int',0x2000,0));let i=0;for(;i<Math.min(src.length,bounded?n:src.length);i++){b.step(condition,'Check the copy loop','The current character is within the permitted copy.','A bounded copy stops at n even if source text continues.','condition → true',()=>{},['i']);if(bounded)b.step("if (src[i] != '\\0')",'Check for source zero',`src[${i}] is not zero.`,'Copy this character rather than padding.','true → copy',()=>{},['s'+i]);b.step('dest[i] = src[i];','Copy one character',`Copy '${src[i]}' from src[${i}] into dest[${i}].`,'Changing dest later would not change src.','src char → independent dest char',()=>b.set('d'+i,src[i]),['s'+i]);b.step('i++;','Advance the index',`Set i to ${i+1}.`,'The next char will use the next pair of cells.','i + 1 → i',()=>b.set('i',i+1));}
  if(bounded&&!truncated){b.step(condition,'Check the bounded loop',`${i} < ${n} is true.`,'There is unused destination capacity.','true → body',()=>{},['i']);b.step("if (src[i] != '\\0')",'Find source zero','src[2] is zero, so use the padding branch.','strncpy-style padding fills every remaining position with zero.','source zero → else',()=>{},['s2']);for(;i<n;i++){b.step(`while (i < ${n})`,'Check the padding loop',`${i} < ${n} is true.`,'No further source characters are read.','true → pad',()=>{},['i']);b.step("dest[i] = '\\0';",'Write a padding zero',`Set dest[${i}] to zero.`,'The destination becomes a terminated string and remains padded.','zero → dest cell',()=>b.set('d'+i,'\\0'));b.step('i++;','Advance padding',`Set i to ${i+1}.`,'Continue until n cells are initialized.','i + 1 → i',()=>b.set('i',i+1));}b.step(`while (i < ${n})`,'End padding',`${n} < ${n} is false.`,'All n cells were written.','false → stop',()=>{},['i']);}
  b.step(condition,'End the copy',bounded?`${n} < ${n} is false.`:'The current source char is zero.','The loop stops without reading beyond the source.', 'false → stop',()=>{},bounded?['i']:['s'+src.length]);if(!bounded)b.step("dest[i] = '\\0';",'Terminate the destination','Copy the required zero terminator after the text.','A C string needs its own zero terminator.','zero → dest end',()=>b.set('d'+src.length,'\\0'));return b.finish(truncated?'printf("%c%c\\n", dest[0], dest[1]);':'printf("%s\\n", dest);',truncated?'He\n':'Hi\n',truncated?'Print exactly two chars. dest has no zero terminator here, so passing it to %s would be unsafe.':'Print the copied string from its own storage.');}
function compare(){const b=new Trace('strcmp','String comparison · first difference','Compare corresponding characters until they differ or both reach zero.',program(['char a[] = "ab";','char b[] = "ac";','int i = 0;',"while (a[i] != '\\0' && a[i] == b[i])",'    i++;','int difference = (unsigned char)a[i] - (unsigned char)b[i];','printf("%d\\n", difference);']));b.step('char a[] = "ab";','Create the first string','Create ab and zero.','Both strings are read only in this example.','chars → a',()=>b.chars('a','ab'));b.step('char b[] = "ac";','Create the second string','Create ac and zero in other cells.','We compare corresponding positions.','chars → b',()=>b.chars('b','ac',0x1100));b.step('int i = 0;','Initialize i','Start at the first pair.','Indexing selects one char from each string.','0 → i',()=>b.cell('i','i','int',0x2000,0));b.step("while (a[i] != '\\0' && a[i] == b[i])",'Compare equal characters',"Both first chars are 'a', and a[0] is not zero.",'No string bytes change.','equal nonzero → continue',()=>{},['a0','b0']);b.step('i++;','Move to the next pair','Increase i to 1.','This compares b against c next.','1 → i',()=>b.set('i',1));b.step("while (a[i] != '\\0' && a[i] == b[i])",'Find a difference',"'b' and 'c' are different. The condition is false.",'The first differing unsigned character values determine the sign.','different → stop',()=>{},['a1','b1']);b.step('int difference = (unsigned char)a[i] - (unsigned char)b[i];','Compute the difference',"For this basic character set, 'b' - 'c' is -1.",'A negative result means a sorts before b. The general contract depends on the sign, not necessarily a magnitude of 1.','unsigned character values → difference',()=>b.cell('difference','difference','int',0x2004,-1),['a1','b1']);return b.finish('printf("%d\\n", difference);','-1\n');}
function atoi(){const b=new Trace('atoi','Text → integer accumulation','Each digit grows the previous value by a factor of ten.',program(['char text[] = "-42";','int i = 0;','int sign = 1;','int value = 0;',"if (text[i] == '-')",'{','    sign = -1;','    i++;','}',"while (text[i] >= '0' && text[i] <= '9')",'{',"    value = value * 10 + text[i] - '0';",'    i++;','}','value = value * sign;','printf("%d\\n", value);']));b.step('char text[] = "-42";','Create the input text','Create minus, 4, 2, and zero.','This is a small parsing example, not the complete whitespace/multiple-sign exercise contract.','text → chars',()=>b.chars('text','-42'));for(const [id,v,loc]of [['i',0,0x2000],['sign',1,0x2004],['value',0,0x2008]])b.step(`int ${id} = ${v};`,'Initialize '+id,`Store ${v} in ${id}.`,'Sign, position, and accumulated value have separate roles.',`${v} → ${id}`,()=>b.cell(id,id,'int',loc,v));b.step("if (text[i] == '-')",'Check the sign','The first char is minus.','The branch reads a char, then changes numeric sign.','minus → true',()=>{},['text0']);b.step('sign = -1;','Record the sign','Store -1.','The digits will first be accumulated as a positive value.','-1 → sign',()=>b.set('sign',-1));b.step('i++;','Skip the sign','Move to index 1.','The next char is the first digit.','1 → i',()=>b.set('i',1));let val=0;for(let i=1;i<3;i++){b.step("while (text[i] >= '0' && text[i] <= '9')",'Recognize a digit',`'${'-42'[i]}' is between 0 and 9.`,'Subtracting character zero will yield its numeric digit.','digit range → true',()=>{},['text'+i]);const old=val;val=val*10+Number('-42'[i]);b.step("value = value * 10 + text[i] - '0';",'Accumulate a decimal place',`${old} × 10 + ${'-42'[i]} = ${val}.`,'Multiplying by 10 shifts previous digits one decimal place.','old value × 10 + digit → value',()=>b.set('value',val),['value','text'+i]);b.step('i++;','Move past the digit',`Set i to ${i+1}.`,'The next condition checks the following character.','i + 1 → i',()=>b.set('i',i+1));}b.step("while (text[i] >= '0' && text[i] <= '9')",'Stop parsing digits','The zero terminator is not a decimal digit.','The loop stops at the first non-digit.','false → stop',()=>{},['text3']);b.step('value = value * sign;','Apply the sign','42 × -1 becomes -42.','Only the numeric value changes. The original text remains intact.','value × sign → value',()=>b.set('value',-42),['value','sign']);return b.finish('printf("%d\\n", value);','-42\n');}

